def main():
    S = input()
    frequency = [0] * 26  # Assuming only lowercase letters a-z

    # Count frequency of each character
    for char in S:
        frequency[ord(char) - ord('a')] += 1

    frequency_count = {}

    # Count how many characters have each frequency
    for freq in frequency:
        if freq > 0:
            if freq in frequency_count:
                frequency_count[freq] += 1
            else:
                frequency_count[freq] = 1

    # Check if all values in frequency_count are zero or two
    for count in frequency_count.values():
        if count != 0 and count != 2:
            print("No")
            return

    print("Yes")

